indexes:
CREATE INDEX `idx_msg_sender` ON `m_message` (
  `senderId`,
  `sentAt` DESC
) WHERE deletedAt IS NULL;

CREATE INDEX `idx_msg_unread` ON `m_message` (
  `conversationId`,
  `readByCount`,
  `sentAt` DESC
) WHERE deletedAt IS NULL AND readByCount < 10;

CREATE INDEX `idx_msg_reply_cover` ON `m_message` (
  `replyToMessageId`,
  `deletedAt`,
  `sentAt` ASC,
  `id`
) WHERE replyToMessageId IS NOT NULL;

CREATE INDEX `idx_msg_roots` ON `m_message` (
  `conversationId`,
  `threadDepth`,
  `sentAt` DESC
) WHERE replyToMessageId IS NULL;

CREATE INDEX `idx_msg_thread_root` ON `m_message` (
  `threadRootId`,
  `threadDepth`,
  `sentAt` ASC
) WHERE threadRootId IS NOT NULL;

CREATE INDEX `idx_msg_popular` ON `m_message` (
  `conversationId`,
  `threadReplyCount` DESC
) WHERE threadReplyCount > 5;
